const app = document.querySelector('#app');
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data, imported = false;
const pct = x => `${(100*x).toFixed(1)}%`;
function validate(value) {
  if (value?.schema_version !== 'rollout-snapshot.v1' || !Array.isArray(value.policies) || !Array.isArray(value.jobs) || !Array.isArray(value.trajectories) || !Array.isArray(value.counts)) throw Error('Expected a rollout snapshot exported by the CLI.');
  if ([value.policies,value.jobs,value.trajectories,value.counts].some(a=>a.length>10000)) throw Error('Snapshot is too large.');
  if (value.demo?.history && (!Array.isArray(value.demo.history) || value.demo.history.length>1000 || value.demo.history.some(p=>!Number.isFinite(p.optimal_action_probability)||p.optimal_action_probability<0||p.optimal_action_probability>1))) throw Error('Invalid learning history.');
  if (!Number.isSafeInteger(value.total_trajectories) || value.total_trajectories < 0 || value.policies.some(p=>!p || !Number.isSafeInteger(p.version) || typeof p.digest!=='string') || value.jobs.some(j=>!j || typeof j.id!=='string' || typeof j.kind!=='string' || typeof j.state!=='string') || value.counts.some(c=>!c || !Number.isSafeInteger(c.count) || c.count<0)) throw Error('Invalid snapshot records.');
  return value;
}
function render() {
  const history=data.demo?.history || [], last=history.at(-1), current=data.policies.at(-1), total=(kind,state)=>data.counts.filter(c=>c.kind===kind&&c.state===state).reduce((n,c)=>n+Number(c.count),0);
  const points=history.map((p,i)=>`${35+i*830/Math.max(1,history.length-1)},${205-p.optimal_action_probability*170}`).join(' ');
  app.innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="/"><span class="brand-mark">↳</span> replay <span class="version">0.4</span></a><div class="eyebrow">ROLLOUT INFRASTRUCTURE</div><nav class="nav" aria-label="Main navigation"><a class="active" href="/">◈ &nbsp; Rollout overview</a><a href="/debugger.html">⇄ &nbsp; Replay & regression</a><a href="/benchmark.html">◷ &nbsp; Benchmarks</a><a href="#workers">↳ &nbsp; Worker jobs</a><a href="#quickstart">⌘ &nbsp; Run locally</a></nav><div class="sidebar-footer"><div class="connection">${imported?'Imported evidence':'Recorded CPU learning run'}</div><p>Every rollout has a policy.<br>Every update has evidence.</p><a href="https://github.com/j112929/agent-replay-mvp">Source on GitHub ↗</a></div></aside><main class="main"><div class="topbar"><span>Infrastructure &nbsp; / &nbsp; <strong>Rollouts</strong></span><span>SNAPSHOT VIEW · NO LIVE CLUSTER CONNECTION</span></div><div class="workspace"><header class="rollout-heading"><div><div class="eyebrow">DISTRIBUTED RL ROLLOUT & REPLAY</div><h1>Train the policy.<br>Keep the evidence.</h1><p>Schedule actors, verify trajectories, replay decisions and trace every weight update.</p></div><button class="primary" id="import-snapshot">Import snapshot ↥</button></header><div class="pipeline" aria-label="Learning pipeline">${['Policy','Scheduler','Actors','Trajectory store','Verifier','Replay / debug','Learner','Weight update'].map((x,i)=>`<span>${escape(x)}</span>${i<7?'<b aria-hidden="true">→</b>':''}`).join('')}</div><div class="metrics"><div class="metric"><span>TRAJECTORIES</span><strong>${escape(data.total_trajectories)}</strong><small>immutable episode evidence</small></div><div class="metric"><span>POLICY VERSION</span><strong>v${escape(current?.version??'—')}</strong><small>${escape(data.policies.length)} retained versions</small></div><div class="metric"><span>VERIFIED EPISODES</span><strong>${escape(total('verifier','done'))}</strong><small>independent reward worker</small></div><div class="metric"><span>OPTIMAL ACTION</span><strong>${last?pct(last.optimal_action_probability):'—'}</strong><small>${history.length?'measured bandit policy probability':'learning history unavailable'}</small></div></div><div class="rollout-grid"><section class="panel"><div class="panel-head"><h2>Policy improvement</h2><span class="muted">${escape(data.demo?.algorithm||'Imported run')}</span></div>${history.length?`<svg viewBox="0 0 900 240" role="img" aria-label="Optimal action probability over policy versions"><path d="M35 35H865 M35 120H865 M35 205H865" class="grid-line"/><text x="0" y="40">100%</text><text x="5" y="125">50%</text><text x="12" y="210">0%</text><polyline points="${points}" class="learning-line"/>${history.map((p,i)=>`<circle cx="${35+i*830/Math.max(1,history.length-1)}" cy="${205-p.optimal_action_probability*170}" r="4"><title>v${escape(p.version)}: ${pct(p.optimal_action_probability)}</title></circle>`).join('')}<text x="35" y="233">Policy v0</text><text x="810" y="233">v${escape(last.version)}</text></svg><p class="chart-caption">${pct(history[0].optimal_action_probability)} → ${pct(last.optimal_action_probability)} · ${escape(data.demo?.rounds)} updates · ${escape(data.demo?.actors)} Actor processes</p>`:'<p class="chart-caption">This snapshot contains no learning history.</p>'}<p class="chart-caption muted">${imported?'User-imported snapshot.':'Recorded execution in a synthetic two-arm bandit environment. Real REINFORCE gradients; no GPU or LLM training.'}</p></section><section class="panel guardrails"><div class="eyebrow">EXECUTION CONTRACT</div><h2>A versioned learning loop.</h2><p><strong>Lease-fenced jobs</strong><br>Expired workers cannot overwrite new results.</p><p><strong>Verified batches</strong><br>Same policy, environment and reward verifier.</p><p><strong>Atomic policy updates</strong><br>Stale learners cannot replace the active policy.</p><p class="muted">Network workers with one SQLite controller. This release does not provide controller high availability or GPU scheduling.</p></section></div><section class="panel" id="workers"><div class="panel-head"><h2>Worker jobs</h2><span class="muted">Latest ${Math.min(12,data.jobs.length)} of ${data.jobs.length} · persisted snapshot</span></div><div class="rollout-table"><table><thead><tr><th>Job</th><th>Role</th><th>State</th><th>Worker</th><th>Attempts</th></tr></thead><tbody>${data.jobs.slice(0,12).map(j=>`<tr><td title="${escape(j.id)}">${escape(j.id.slice(0,28))}…</td><td>${escape(j.kind)}</td><td><span class="job-state">${escape(j.state)}</span></td><td>${escape(j.owner||'—')}</td><td>${escape(j.attempts)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel lineage"><div class="panel-head"><h2>Weight lineage</h2><span class="muted">Immutable content hashes</span></div><div class="policy-list">${data.policies.map(p=>`<div><strong>v${escape(p.version)}</strong><code>${escape(p.digest.slice(0,12))}</code><small>${p.parent===null?'Initial policy':`Parent v${escape(p.parent)}`}</small></div>`).join('')}</div></section><section class="panel guardrails" id="quickstart"><div class="eyebrow">RUN THE COMPLETE LOOP</div><h2>Three actors. Eight policy updates. One command.</h2><pre>pip install -e .
agent-replay rollout demo --actors 3 --rounds 8</pre><p>The CLI starts a temporary HTTP controller and separate Actor, Verifier and Learner processes. Import the resulting <code>snapshot.json</code> here, or open exported <code>trace.json</code> in the debugger.</p><p><a href="/debugger.html">Open Replay / Regression Debugger ↗</a> &nbsp; <a href="https://github.com/j112929/agent-replay-mvp/blob/main/docs/rollout-infrastructure.md">Architecture and worker setup ↗</a> &nbsp; <a href="/agent-replay-mvp.zip">Download source ZIP ↓</a></p></section><div class="footer"><span>Rollout → Verify → Replay → Learn → Update</span><span>Hosted evidence viewer · execution runs on your workers</span></div></div></main></div>`;
  document.querySelector('#import-snapshot').onclick=()=>document.querySelector('#snapshot-file').click();
}
document.querySelector('#snapshot-file').onchange=async event=>{
  const file=event.target.files[0]; if(!file)return;
  try {if(file.size>5*1024*1024)throw Error('Snapshot exceeds 5 MB.'); const candidate=validate(JSON.parse(await file.text())); data=candidate; imported=true; render();}
  catch(error){document.querySelector('#toast').textContent=error.message;}
  finally{event.target.value='';}
};
try {const response=await fetch('/rollout-demo.json'); if(!response.ok)throw Error('Demo evidence unavailable'); data=validate(await response.json()); render();}
catch(error){app.textContent=error.message;}
